from engine import span
def build(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    P = []
    P.append(dict(role='purpose', text='El Siglo de Oro español abarca dos fases estéticas: el Renacimiento del siglo XVI y el Barroco del siglo XVII. Este capítulo estudia la segunda con tres figuras que la definen y que se conocieron y se enfrentaron entre sí: Lope de Vega, que renovó el teatro; Luis de Góngora, máximo exponente del culteranismo; y Francisco de Quevedo, escritor del conceptismo.',
        quotes=[Q('es_siglo_oro','El Siglo de Oro abarca dos periodos estéticos, que corresponden al Renacimiento del siglo XVI','Barroco del siglo XVII'), Q('en_golden_age','It produced many of the best-known figures in Spanish cultural history, including Miguel de Cervantes, Lope de Vega, Luis de Góngora, Francisco de Quevedo')]))
    P.append(dict(text='El Siglo de Oro no se enmarca en fechas concretas, aunque suele situarse entre 1492 y 1659, año del Tratado de los Pirineos, y se prolonga en términos culturales hasta 1681, año de la muerte de Calderón de la Barca. El término Siglo de Oro surgió en el siglo XVIII por analogía con las edades del hombre de Hesíodo. Al lenguaje claro y popular del siglo XVI sucede en el Barroco una lengua más oscura, propia de una reacción religiosa, nobiliaria y cortesana que corresponde a una época de crisis política, económica y social.',
        quotes=[Q('es_siglo_oro','El Siglo de Oro no se enmarca en fechas concretas','el año 1659'), Q('en_golden_age','the period is commonly understood to have continued in cultural terms until 1681, the year of Pedro Calderón de la Barca\'s death'), Q('es_siglo_oro','una reacción religiosa, nobiliaria y cortesana de signo Barroco')]))
    P.append(dict(text='Lope de Vega nació en Madrid el 25 de noviembre de 1562 y murió allí el 27 de agosto de 1635. Cervantes lo llamó Fénix de los ingenios y Monstruo de Naturaleza. Es, junto con Tirso de Molina y Calderón, uno de los máximos exponentes del teatro barroco español, y fue también un gran lírico: se le atribuyen unos tres mil sonetos. Su vida fue tan extrema como su obra: fue condenado al destierro por injurias contra el comediante Jerónimo Velázquez y se ordenó sacerdote el 24 de mayo de 1614, tras la muerte de su hijo Carlos Félix y de su esposa Juana de Guardo.',
        quotes=[Q('es_lope','Madrid, 25 de noviembre de 1562-Madrid, 27 de agosto de 1635'), Q('en_lope','Cervantes said that Lope de Vega was “The Phoenix of Wits” (Fénix de los ingenios) and “Monster of Nature” (Monstruo de naturaleza).'), Q('es_lope','el 24 de mayo de 1614 decidió al fin ser ordenado sacerdote'), Q('es_lope','la condena al destierro contra Lope a causa de las injurias contra el comediante Jerónimo Velázquez y su familia')]))
    P.append(dict(text='La cantidad de su obra dramática no es cierta, y las fuentes discrepan. Una afirma que se le atribuyen varios centenares de comedias, hasta 1800 según su biógrafo Juan Pérez de Montalbán; otra habla de unas quinientas; otra, de alrededor de mil, de las que se conservan más de cuatrocientas. Conviene citar la cifra con su fuente y no elegir una: un lector prudente trata el número exacto como una incógnita y retiene solo lo común, que escribió centenares de comedias y que es uno de los autores más prolíficos de la literatura universal.',
        quotes=[Q('es_lope','varios centenares de comedias (1800 según Juan Pérez de Montalbán)'), Q('en_lope','approximately 500 stageplays'), Q('en_golden_age','who wrote around 1,000 plays during his lifetime, of which over 400 survive to the present day')]))
    P.append(dict(text='En 1609 Lope leyó ante la Academia de Madrid el Arte nuevo de hacer comedias en este tiempo, un texto en verso de 389 versos que se publicó ese mismo año junto a sus sonetos. En él defiende un teatro basado en el gusto del público de los corrales de comedias sin enfrentarse a la tradición académica: declara conocer la Poética de Aristóteles y haber compuesto seis comedias según las unidades, pero afirma haber encerrado «los preceptos con seis llaves» porque los tiempos reclamaban otro espectáculo.',
        quotes=[Q('es_arte_nuevo','El Arte nuevo de hacer comedias en este tiempo es un texto ensayístico en verso de Lope de Vega que leyó como discurso ante la Academia de Madrid en 1609'), Q('es_arte_nuevo','a lo largo de sus 389 versos'), Q('es_lope','En 1609 leyó y publicó su Arte nuevo de hacer comedias')]))
    P.append(dict(text='La comedia nueva de Lope rompe con los preceptos clásicos en varios puntos: divide la trama en tres actos, que corresponden a planteamiento, nudo y desenlace, y adopta la tragicomedia, que mezcla lo risible y lo serio en una misma obra, rasgo muy barroco por su búsqueda de variedad y fusión de contrarios. Entre sus obras más celebradas están Peribáñez y el comendador de Ocaña (1610), Fuenteovejuna (1612-1614), La dama boba (1613) y El caballero de Olmedo, que se divide en tres episodios que corresponden a planteamiento, nudo y desenlace.',
        quotes=[Q('es_arte_nuevo','la división de la trama (en tres actos, adecuándolos linealmente al orden "planteamiento, nudo y desenlace")'), Q('es_arte_nuevo','la mezcla de lo risible y serio en una misma obra'), Q('es_lope','Peribáñez y el comendador de Ocaña (1610), Fuenteovejuna (1612-1614), La dama boba (1613)')]))
    P.append(dict(text='Luis de Góngora nació en Córdoba el 11 de julio de 1561 y murió allí en 1627, en la pobreza y tras perder la memoria por una grave enfermedad. Las dos fuentes difieren en un día: una fecha su muerte el 23 de mayo de 1627 y la otra el 24 de mayo. Fue canónigo de la catedral de Córdoba, sacerdote y capellán real de Felipe III desde 1617. Se le considera el poeta más original e influyente del Barroco español, y entre sus obras mayores figuran la Fábula de Polifemo y Galatea y las Soledades.',
        quotes=[Q('es_gongora','Córdoba, 11 de julio de 1561-Córdoba, 23 de mayo de 1627'), Q('en_gongora','11 July 1561 – 24 May 1627'), Q('es_gongora','Entre sus obras mayores sobresalen la Fábula de Píramo y Tisbe, la Fábula de Polifemo y Galatea y las Soledades.')]))
    P.append(dict(text='La poesía de Góngora suele dividirse en dos períodos. Hasta 1610 usa metros cortos y temas ligeros, como décimas, romances y letrillas; después se vuelve culterano, con metáforas difíciles, alusiones mitológicas, cultismos e hipérbatos. Dámaso Alonso demostró, sin embargo, que estas dificultades ya aparecían en su primera época y que la segunda es una intensificación de los mismos recursos por motivos estéticos. En 1613 difundió en la Corte las Soledades, que desataron una gran polémica por su oscuridad y afectación.',
        quotes=[Q('es_gongora','En el tradicional hace uso de los metros cortos y temas ligeros','estaban ya presentes en su primera época'), Q('es_gongora','el mismo año divulgó en la Corte su poema más ambicioso, las incompletas Soledades'), Q('en_gongora','His style is characterized by what was called culteranismo, also known as Gongorismo.')]))
    P.append(dict(text='Francisco de Quevedo nació en Madrid el 14 de septiembre de 1580 y murió en Villanueva de los Infantes el 8 de septiembre de 1645. Nació cojo y con severa miopía, y su nombre en plural, quevedos, pasó a designar unos anteojos. Fue caballero de la Orden de Santiago, estudió con los jesuitas y fue secretario del duque de Osuna. Escribió poesía, la novela picaresca La vida del Buscón, los Sueños y tratados políticos y morales como la Política de Dios. Hacia el final de su vida fue encarcelado en el convento de San Marcos de León sin proceso.',
        quotes=[Q('es_quevedo','Madrid, 14 de septiembre de 1580','8 de septiembre de 1645'), Q('en_quevedo','his name in the plural, quevedos, came to mean "pince-nez" in the Spanish language'), Q('es_quevedo','la primera versión manuscrita de una novela picaresca, La vida del Buscón')]))
    P.append(dict(text='Góngora y Quevedo mantuvieron una célebre enemistad, que algunos críticos consideran un ejercicio de rivalidad frecuente en la poesía barroca. Según la tradición, empezó en Valladolid hacia 1603, cuando los primeros poemas de Quevedo imitaban o parodiaban los de Góngora, y Góngora lo atacó con una serie de versos. Quevedo respondió con sátiras tan duras como «A una nariz». Hay que tomar con cautela las atribuciones de las sátiras a uno y otro, porque son bastante dudosas.',
        quotes=[Q('es_quevedo','Antonio Carreira o Amelia de Paz dudan de que dicha enemistad durase demasiado','ejercicios habituales en la poesía barroca'), Q('en_gongora','He maintained a long feud with Francisco de Quevedo'), Q('es_gongora','Durante una estancia en la Corte de Valladolid en 1603 se enemistó con Francisco de Quevedo')]))
    P.append(dict(role='definition', text='Culteranismo y conceptismo son las dos grandes corrientes del Barroco literario español. El culteranismo, también llamado gongorismo, aboga por la perífrasis embellecedora y por la latinización de la sintaxis y el léxico mediante el hipérbaton y los cultismos. El conceptismo busca una concisión exacta, que concentre el máximo significado en las menores palabras posibles, mediante juegos de palabras y dobles sentidos; para Baltasar Gracián, el concepto es un acto del entendimiento que expresa la correspondencia que se halla entre los objetos.',
        quotes=[Q('es_culteranismo','el culteranismo aboga por la perífrasis embellecedora y la elusión del vocabulario común'), Q('es_conceptismo','Un acto del entendimiento que expresa la correspondencia que se halla entre los objetos'), Q('en_quevedo','His style is characterized by what was called conceptismo.')]))
    P.append(dict(role='consejo', text='Cuando lea a Góngora, no se detenga en cada palabra difícil: identifique primero el esqueleto de la oración, desplazado por el hipérbaton, y después las alusiones mitológicas. Con Quevedo, en cambio, busque el doble sentido y la elipsis, que concentran en pocos versos lo que Góngora dispersa en un laberinto. Así distinguirá por el procedimiento, y no por la fama, una poesía de la otra.',
        quotes=[Q('es_culteranismo','Latinización de la sintaxis mediante un extremo y violento hipérbaton'), Q('es_conceptismo','La concisión, la elipsis y el zeugma son las piedras angulares de esta retórica.'), Q('en_gongora','This style apparently existed in stark contrast to Quevedo\'s conceptismo')]))
    P.append(dict(role='self_check', text='¿Qué defendió Lope en el Arte nuevo y por qué lo hizo ante la Academia? ¿En qué se diferencian el culteranismo de Góngora y el conceptismo de Quevedo? ¿Por qué debe citarse con su fuente el número de comedias de Lope?',
        quotes=[Q('es_arte_nuevo','En el Arte nuevo Lope intenta defender un teatro basado en el gusto de la época'), Q('en_golden_age','Lope de Vega, Spain\'s most prolific playwright')]))
    return P

def problems(spec):
    Q = lambda k, a, b=None: span(spec, k, a, b)
    return [dict(role='worked', problem_type='NUMERICAL',
        prompt='Quevedo nació el 14 de septiembre de 1580 y Góngora murió el 23 de mayo de 1627. Calcule durante cuántos años (con una cifra decimal) coincidieron vivos ambos poetas. Entre las dos fechas hay 17 052 días; use 365,25 días por año.',
        expected='46.7', quotes=[Q('es_quevedo','Madrid, 14 de septiembre de 1580'), Q('es_gongora','Córdoba, 11 de julio de 1561-Córdoba, 23 de mayo de 1627')],
        method='Diferencia de fechas convertida a años',
        solution=dict(given=[dict(symbol='d',value=17052,unit='dimensionless',meaning='días entre el 14-09-1580 y el 23-05-1627'),dict(symbol='y',value=365.25,unit='dimensionless',meaning='días por año medio')],
          unknown='Los años en que ambos poetas estuvieron vivos a la vez.',
          model=[dict(name='Años de coincidencia',latex='T = d / y',symbolic='d/y')],
          assumptions=['Ambos poetas están vivos desde el nacimiento de Quevedo hasta la muerte de Góngora.','Se cuentan los días del calendario gregoriano proléptico, sin corregir los diez días de la reforma de 1582.'],
          development=['Como Góngora nació antes que Quevedo y murió antes, el intervalo de coincidencia va del nacimiento del más joven a la muerte del mayor.'],
          steps=[dict(text='Años de coincidencia',equation='T = 17052 / 365.25',expression='17052/365.25',expected=46.6858,unit='dimensionless')],
          result='Coincidieron vivos unos 46,7 años.',
          interpretation='Coincidieron casi medio siglo, tiempo suficiente para la enemistad literaria y para que Quevedo conociera la obra de Góngora, que circulaba en manuscritos.',
          limitations=['La corrección de diez días del calendario cambia el resultado en 0,03 años, que no altera la cifra redondeada.'],
          mistakes=['Restar solo los años 1627 - 1580 = 47, que ignora los meses y exagera el intervalo en unos cuatro meses.']))]
